Mobile Lighthouse LCP on / and the exhibit page is about 3.86 s (gate 2.5 s) although the observed h1 paint is 0.42 to 0.54 s. Lantern counts every request that starts before the observed LCP, and src/overlay/MuseumGate.tsx starts the museum import (MuseumCanvas 86 KB plus the three.js chunk 240 KB) before the hero paints: immediately after hydration under ?test=1, and after load plus idle otherwise (load fires before first paint on a fast server; measured on /?mode=museum too, 3848 ms). Request for the MuseumGate owner (src/overlay/**, WP-30 this milestone): start the import only after the first contentful paint, document.fonts.ready and one frame, on both paths. With the patch below applied locally and rebuilt, mobile LCP was 2027 ms (/) and 2081 ms (exhibit page), and the museum chunk was requested after the LCP. The patch is a sketch: its 3 s fallback timer and the paint observer should also be cleared in the effect cleanup. Patch:
diff --git a/src/overlay/MuseumGate.tsx b/src/overlay/MuseumGate.tsx
index bcb4e76..8ac19ed 100644
--- a/src/overlay/MuseumGate.tsx
+++ b/src/overlay/MuseumGate.tsx
@@ -36,6 +36,29 @@ const MuseumCanvas = lazy(() =>
 const START_EVENTS = ['scroll', 'pointerdown', 'keydown'] as const;
 const IDLE_TIMEOUT_MS = 2000;

+/** Calls `then` once the first contentful paint has happened (at most 3 s later without one). */
+function afterFirstPaint(then: () => void): void {
+  let called = false;
+  const once = () => {
+    if (called) return;
+    called = true;
+    // The web fonts repaint the hero (often the LCP entry): wait for them and one more frame.
+    const fonts = document.fonts ? document.fonts.ready : Promise.resolve();
+    void fonts.then(() => requestAnimationFrame(() => window.setTimeout(then, 0)));
+  };
+  if (performance.getEntriesByName('first-contentful-paint').length > 0) return once();
+  try {
+    const observer = new PerformanceObserver(() => {
+      observer.disconnect();
+      once();
+    });
+    observer.observe({ type: 'paint', buffered: true });
+  } catch {
+    // No paint timing: fall through to the timeout.
+  }
+  window.setTimeout(once, 3000);
+}
+
 /** Resolves the trigger once: load plus idle, a first interaction, or ?test=1. */
 function useStartSignal(): boolean {
   const [start, setStart] = useState(false);
@@ -64,14 +87,19 @@ function useStartSignal(): boolean {
     }
     if (testParams(window.location.search).test) {
       // Immediately, but after hydration has committed (the prerender rendered no museum).
-      timer = window.setTimeout(go, 0);
+      afterFirstPaint(() => {
+        timer = window.setTimeout(go, 0);
+      });
       return cleanup;
     }
     for (const type of START_EVENTS) {
       window.addEventListener(type, go, { passive: true, once: true });
     }
-    if (document.readyState === 'complete') afterLoad();
